// Parse JSON response từ Gemini
const rawText = $input.first().json.text || '';

// Strip markdown code blocks nếu có
let cleanText = rawText.trim();
if (cleanText.startsWith('```json')) {
  cleanText = cleanText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
} else if (cleanText.startsWith('```')) {
  cleanText = cleanText.replace(/^```\n?/, '').replace(/\n?```$/, '');
}

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  // Fallback nếu parse lỗi
  parsed = {
    category: 'Khác',
    summary: rawText.substring(0, 200),
    key_points: 'Không phân tích được|Vui lòng thử lại|',
    suggestions: 'Hãy mô tả ý tưởng rõ hơn|',
    risks: 'Không xác định|',
    next_steps: 'Mô tả chi tiết hơn rồi gửi lại|',
    rating: '5',
    telegram_reply: '⚠️ AI gặp lỗi khi phân tích. Hãy thử mô tả ý tưởng rõ ràng hơn nhé!'
  };
}

// Lấy context từ Set node
const ctx = $('Set: Extract Message Data').first().json;

return {
  json: {
    ...parsed,
    user_message: ctx.user_message,
    user_name: ctx.user_name.trim() || ctx.username,
    username: ctx.username,
    chat_id: ctx.chat_id,
    message_id: ctx.message_id,
    timestamp: ctx.timestamp,
    date_only: ctx.date_only,
    // Chuẩn hoá rating
    rating: parseInt(parsed.rating) || 5
  }
};
